
<h1>Tasks</h1><p>Clear ownership. Visible progress.</p>
<?php if($manager): ?><details><summary>+ Allocate a task</summary><form method="post" class="grid"><?=csrf()?><input type="hidden" name="action" value="create_task"><label>Task title<input name="title" maxlength="200" required></label><label>Employee<select name="employee_id" required><option value="">Select employee</option><?php foreach($employees as $emp): ?><option value="<?=e($emp['id'])?>"><?=e($emp['name'])?></option><?php endforeach ?></select></label><label>Due date<input type="date" name="due_date" min="<?=e($today)?>" required></label><label>Priority<select name="priority"><option>medium</option><option>high</option><option>low</option></select></label><label>Description<textarea name="description" maxlength="5000"></textarea></label><div><button>Allocate task</button></div></form></details><?php endif ?>
<form method="get" class="filter"><input type="hidden" name="page" value="tasks"><label>Filter<select name="status"><?php foreach([''=>'All tasks','todo'=>'To do','in_progress'=>'In progress','pending'=>'Pending','completed'=>'Completed','overdue'=>'Overdue'] as $v=>$l): ?><option value="<?=$v?>" <?=$status===$v?'selected':''?>><?=$l?></option><?php endforeach ?></select></label><button>Apply</button></form>
<?php if(!$tasks): ?><section>No tasks match this filter.</section><?php endif ?>
<?php foreach($tasks as $t): ?><section class="task"><div><span class="tag"><?=e($t['priority'])?></span><?php if($t['status']!=='completed' && $t['due_date']<$today): ?><span class="overdue">Overdue</span><?php endif ?><h2><?=e($t['title'])?></h2><p class="preserve"><?=e($t['description'])?></p><small><?=e($t['name'])?> · Due <?=e($t['due_date'])?></small></div><form method="post"><?=csrf()?><input type="hidden" name="action" value="status"><input type="hidden" name="task_id" value="<?=e($t['id'])?>"><input type="hidden" name="version" value="<?=e($t['version'])?>"><label>Status<select name="status"><?php foreach(['todo','in_progress','pending','completed'] as $s): ?><option <?=$s===$t['status']?'selected':''?>><?=$s?></option><?php endforeach ?></select></label><button>Update</button></form></section><?php endforeach ?>
<div class="filter"><?php if($offset): ?><a href="?page=tasks&status=<?=e($status)?>&offset=<?=max(0,$offset-50)?>">Previous</a><?php endif ?><?php if($more): ?><a href="?page=tasks&status=<?=e($status)?>&offset=<?=$offset+50?>">Next</a><?php endif ?></div>
